Method.Implementation:
Set PID3Cnt = pSource.GetValueAt("PID:3(*)")
Set UnitNum = ""
for i=1:1:PID3Cnt
{
	//Get 
	Set aaNm = pSource.GetValueAt("PID:3("_i_").4.1")
	If aaNm = "UN"
	{
		Set UnitNum = pSource.GetValueAt("PID:3("_i_").1")
		Quit
	}
}
Quit UnitNum

Set status = $$$OK Set out = "" try{ Set expX = ##class(%Regex.Matcher).%New("XX+") Set expS = ##class(%Regex.Matcher).%New(" +") Set expX.Text = input Set out = expX.ReplaceAll("") Set expS.Text = out Set out = expS.ReplaceAll(" ") } Catch(e) { Set out = input Do $system.Status.DecomposeStatus(%objlasterror,.Err) Set status = $$$ERROR($$$GeneralError,"Regex error "_Err(Err))
;W err,!
} Quit status

Set status = $$$OK
Set today = +##class(%SYSTEM.SYS).Horolog()
try{
	Set birthday = $ZDATEH(dob,8)
	Set Age = $Piece($ZDATE($Horolog,3),"-") - $Piece($ZDATE(birthday,3),"-")
	//Check if current month is less than DOB month, if yes, reduce 1 from Age
	If ($Piece($ZDATE($Horolog,3),"-",2)<$Piece($ZDATE(birthday,3),"-",2))
	{
		Set Age = Age-1
	}
	//Check if current month is equals to DOB month, if yes, check current date is less than DOB date, if yes,reduce 1 from Age 
	elseif(($Piece($ZDATE($Horolog,3),"-",2)=$Piece($ZDATE(birthday,3),"-",2))&&($Piece($ZDATE($Horolog,3),"-",3)<$Piece($ZDATE(birthday,3),"-",3)))
	{
		Set Age = Age-1
	}
}
Catch(e)
{	
	Set status = $$$ERROR($$$GeneralError,"Date of birth : "_dob_" has a wrong format - "_system.Status.DisplayError(%objlasterror) )
	Throw status
	;W err,!

}
Quit status
